#include <deque>
#include <iostream>

int main() {
    std::deque<int> d;
    // d.reserve(100); // ERROR: Deque does not support reserve()

    // Deque grows by allocating blocks internally
    for (int i = 0; i < 1000; ++i) {
        d.push_back(i);
    }

    // Deque memory may shrink when elements are removed from ends
    // (Behavior is implementation-dependent)
    d.clear(); 

    // Accessing contiguous storage via data() is not possible
    // auto ptr = d.data(); // ERROR: Deque lacks data() method
}
